```verilog
`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires matching TopModule interface
    reg        clk;
    reg  [7:0] d;
    wire [7:0] q;

    // Instantiate the Design Under Test (DUT)
    TopModule dut (
        .clk(clk),
        .d(d),
        .q(q)
    );

    // Clock generation: 10ns period (5ns high, 5ns low)
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    initial begin
        // Initialize signals
        clk = 0;
        d   = 8'h00;
        #12; // Wait past the first clock edge

        // Apply a concise set of test vectors and check registered output
        for (i = 0; i < 15; i = i + 1) begin
            // Apply new input data
            d = $random;

            // Wait for positive clock edge
            @(posedge clk);

            // Wait a small delta for non-blocking assignment to settle
            #1; 

            // Verify that output matches the expected input from the previous cycle
            if (q !== d) begin
                $display("ERROR: Time=%0t | d=%h, q=%h (Expected %h)", $time, d, q, d);
                errors = errors + 1;
            end
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
```

